             or e.contact_phone like concat('%', #{params.adminKeyword}, '%')
             or parent.phonenumber like concat('%', #{params.adminKeyword}, '%'))

     and e.enrollment_code = #{enrollmentCode}
     and e.schedule_id = #{scheduleId}
     and e.parent_id = #{parentId}
     and e.student_name like concat('%', #{studentName}, '%')
     and e.student_phone = #{studentPhone}
     and e.contact_phone = #{contactPhone}
     and e.enrollment_status = #{enrollmentStatus}
     and e.pay_status = #{payStatus}
     and e.cancel_time = #{cancelTime}
     and e.cancel_reason = #{cancelReason}
     and e.status = #{status}

order by e.create_time desc, e.enrollment_id desc

