update edu_enrollment
enrollment_code = #{enrollmentCode}, schedule_id = #{scheduleId}, parent_id = #{parentId}, student_name = #{studentName}, student_phone = #{studentPhone}, contact_phone = #{contactPhone}, pay_status = #{payStatus}, cancel_reason = #{cancelReason}, status = #{status}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where enrollment_id = #{enrollmentId}
